class ServiceError(RuntimeError):
    pass


def call(path, port, fallback, timeout=60):
    try:
        return S.request(path, port=port, timeout=timeout), "server"
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise ServiceError(f"检索服务 HTTP {exc.code}: {detail}") from exc
    except (urllib.error.URLError, TimeoutError, ConnectionError):
        return fallback(), "in-process"


def _network(args, path, fallback):
    if getattr(args, "no_server", False):
        return fallback(), "in-process"
    return call(path, args.port, fallback)


def _fallback_search(args):
    import kb_rag
    return kb_rag.retrieve(
        args.query, k=args.k, mode=args.mode,
        type_filter=[x.strip() for x in args.type.split(",") if x.strip()],
        candidate_k=args.candidate_k, rerank_k=args.rerank_k,
        reranker_model=args.reranker_model or None,
        allow_download=args.allow_download)


def _fallback_route(args):
    import kb_route as R
    layers = K.parse_layers(args.layer)
    if not args.layer and args.no_corpus:
        layers = (1, 2)
    return R.route(args.query, budget=K.parse_budget(args.budget), layers=layers)


def _fallback_corpus(args):
    import kb_corpus as C
    rows = C.search(args.query, k=args.k)
    return {"schema_version": "kb.corpus.v1", "ok": True, "mode": "corpus",
            "query": args.query, "count": len(rows), "results": rows}


def _fallback_resolve(args):
    import kb_search as KS
    meta, _ = KS.load_index()
    return {"query": args.query,
            "alias_hits": KS.resolve_aliases(args.query, meta.get("alias_map", {}))}


def _fallback_stats():
    import kb_search as KS
    meta, bm = KS.load_index()
    return {"pages": meta.get("count"), "alias_entries": len(meta.get("alias_map", {})),
            "vocab": len(bm.get("df", {})), "n_docs": bm.get("n_docs"),
            "bm25_version": bm.get("_version", 1)}


def _fallback_ask(args):
    import kb_agentic
    import kb_rag
    decision = kb_agentic.classify_query(args.query)
    strategy = decision["strategy"] if args.strategy == "auto" else args.strategy
    # 显式给了外部 plan ⇒ 必须按 agentic 执行；否则 auto 判成 simple 时 plan 被静默忽略
    if args.plan:
        strategy = "agentic"
    if strategy == "simple":
        data = kb_rag.retrieve(
            args.query, k=args.k, mode=args.mode,
            candidate_k=args.candidate_k, rerank_k=args.rerank_k,
            reranker_model=args.reranker_model or None,
            allow_download=args.allow_download)
        data["classification"] = decision
        return data
    return kb_agentic.run(args.query, plan_path=args.plan or None,
                          max_steps=args.max_steps, budget=K.parse_budget(args.budget),
                          graph_expansion=not args.no_graph)


def _delegate(module_name, argv):
    import importlib
    module = importlib.import_module(module_name)
    old = sys.argv
    try:
        sys.argv = [module_name + ".py"] + list(argv)
        result = module.main()
        return int(result or 0)
    except SystemExit as exc:
        return int(exc.code or 0)
    finally:
        sys.argv = old


def _delegate_family(family, operation, argv):
    operation = operation.replace("-", "_")
    if family == "qc" and operation == "author_gate":
        module_name = "qc_author_gate_apply" if "--apply" in argv else "qc_author_gate"
    else:
        module_name = f"{family}_{operation}"
        path = os.path.join(HERE, module_name + ".py")
        if not os.path.isfile(path):
            raise ValueError(f"未知 {family} 工具：{operation}")
    return _delegate(module_name, argv)


def _add_network(p):
    p.add_argument("--port", type=int, default=S.DEFAULT_PORT)
    p.add_argument("--no-server", action="store_true")


def _add_rag(p):
    p.add_argument("-k", type=int, default=10)
    p.add_argument("--mode", choices=["bm25", "semantic", "hybrid"], default="hybrid")
    p.add_argument("--candidate-k", type=int, default=0)
    p.add_argument("--rerank-k", type=int, default=0)
    p.add_argument("--reranker-model", default="")
    p.add_argument("--allow-download", action="store_true",
                   help="显式允许首次下载 Reranker；默认只读本地模型")


