def normalize_legacy(argv):
    if not argv or argv[0] in COMMANDS or argv[0] in ("-h", "--help"):
        return argv
    if "--selftest" in argv:
        return ["selftest"]
    if "--doctor" in argv:
        return ["doctor"] + [x for x in argv if x != "--doctor"]
    if "--stats" in argv:
        return ["stats"] + [x for x in argv if x != "--stats"]
    for flag, command in (("--route", "route"), ("--corpus", "corpus"),
                          ("--resolve", "resolve")):
        if flag in argv:
            return [command] + [x for x in argv if x != flag]
    return ["search"] + argv


def _print_search(data):
    print(f"[{data.get('mode')}] {data.get('query')}：{data.get('count', 0)} 条")
    for item in data.get("results") or []:
        print(f"{item.get('rank', '-'):>2}. [{item.get('type')}] {item.get('name')}  "
              f"{item.get('score', 0):.4f}")
        if item.get("path"):
            print(f"    {item['path']}")
    for warning in data.get("warnings") or []:
        print(f"[!] {warning}", file=sys.stderr)


def _print_ask(data):
    if data.get("strategy") == "traditional":
        _print_search(data)
        return
    print(f"[agentic:{data.get('status')}] {data.get('query')}")
    print(f"步骤 {len(data.get('steps') or [])}｜证据 {data.get('counts')}｜"
          f"停止 {((data.get('stop') or {}).get('reason'))}")
    for item in (data.get("evidence") or [])[:12]:
        loc = item.get("citation") or item.get("path") or item.get("name")
        print(f"  [{item.get('layer')}] {loc}")
    for gap in data.get("gaps") or []:
        print(f"  [gap] {gap}")
    print("综合请求已包含在 JSON synthesis_request 中；本工具不代替外部 LLM 生成答案。")


def doctor(port, check_reranker=False, allow_download=False):
    ok = True
    print("=== kb doctor ===")
    print(f"库根: {K.VAULT}")
    for path, label, required in ((K.META_PATH, "meta.json", True),
                                  (K.BM25_PATH, "bm25.json", True),
                                  (K.META_FM_PATH, "meta_fm.json", True),
                                  (K.FULL_PATH, "meta_full.json", True),
                                  (K.META_LITE_PATH, "meta_lite.json", False)):
        exists = os.path.exists(path)
        print(f"  [{'ok' if exists else ('FAIL' if required else '--')}] {label}")
        ok = ok and (exists or not required)
    try:
        import kb_semantic_search as SEM
        _em, embed_map = SEM._load_embeddings()
        if embed_map is None:
            print("  [FAIL] 嵌入索引不存在")
            ok = False
        else:
            missing, stale, fresh = SEM.check_index_freshness(embed_map, verbose=False)
            print(f"  [{'ok' if fresh else 'FAIL'}] 嵌入覆盖：缺失 {len(missing)}，幽灵 {len(stale)}")
            ok = ok and fresh
    except Exception as exc:
        print(f"  [FAIL] 语义索引：{exc}")
        ok = False
    try:
        import kb_corpus as C
        corpus = C.check_corpus_freshness()
        print(f"  [{'ok' if corpus['ok'] else 'FAIL'}] 原文语料："
              f"缺失 {len(corpus.get('missing', []))}，幽灵 {len(corpus.get('stale', []))}，"
              f"内容变化 {len(corpus.get('changed', []))}"
              + (f"，{corpus['reason']}" if corpus.get("reason") else ""))
        ok = ok and corpus["ok"]
    except Exception as exc:
        print(f"  [FAIL] 原文语料：{exc}")
        ok = False
    import kb_rag
    print(f"  [config] Reranker={kb_rag.reranker_name()}（默认仅本地）")
    if check_reranker:
        try:
            kb_rag.load_reranker(allow_download=allow_download)
            print("  [ok] Reranker 可加载")
        except kb_rag.RetrievalUnavailable as exc:
            print(f"  [FAIL] {exc}")
            ok = False
    health = S.ping(port)
    print(f"  [{'ok' if health else '--'}] 常驻服务"
          + (f" pid={health['pid']}" if health else " 未运行"))
    print("=== doctor", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def selftest():
    ok = True
    checks = [
        (normalize_legacy(["abc"]) == ["search", "abc"], "旧默认查询兼容"),
        (normalize_legacy(["abc", "--route"]) == ["route", "abc"], "旧 --route 兼容"),
        (K.parse_budget("5,5,8") == {"L1": 5, "L2": 5, "L3": 8}, "预算解析"),
        (K.parse_layers("1,2") == (1, 2), "层解析"),
        (set(K.TYPE_DIR.values()) == set(K.PAGE_DIRS), "类型目录完整"),
    ]
    for condition, label in checks:
        print(f"  [{'ok' if condition else 'FAIL'}] {label}")
        ok = ok and condition
    import kb_agentic
    import kb_rag
    ok = kb_agentic.selftest() == 0 and ok
    ok = kb_rag.selftest() == 0 and ok
    print("SELFTEST", "PASSED" if ok else "FAILED")
    return 0 if ok else 1


def main(argv=None):
    argv = normalize_legacy(list(sys.argv[1:] if argv is None else argv))
    ap = build_parser()
    args = ap.parse_args(argv)
    started = time.time()
    try:
        if args.command == "selftest":
            return selftest()
        if args.command == "doctor":
            return doctor(args.port, args.check_reranker, args.allow_download)
        if args.command in ("lit", "qc", "sci"):
            return _delegate_family(args.command, args.operation, args.args)
        if args.command == "lint":
            return _delegate("kb_lint", args.args)
        if args.command == "toolcheck":
            return _delegate("kb_toolcheck", args.args)
        if args.command == "tools":
            tail = (["--tool", args.tool] if args.tool else [])
            if args.json:
                tail.append("--json")
            return _delegate("kb_manifest", tail)
        if args.command == "serve":
            tail = [] if args.action == "start" else ["--" + args.action]
            if args.warm:
                tail.append("--warm")
            return _delegate("kb_serve", ["--port", str(args.port)] + tail)
        if args.command == "index":
            if args.action == "embed":
                return _delegate("kb_semantic_search",
                                 (["--add"] + args.pages) if args.pages else ["--build"])
            if args.action == "corpus":
                return _delegate("kb_corpus", ["--build"])
            tail = []
            if args.action == "add":
                if not args.pages:
                    ap.error("index add 需要页面路径")
                tail = ["--add"] + args.pages
            if args.full:
                tail.append("--full")
            if args.lite:
                tail.append("--lite")
            if args.action == "stats":
                tail.append("--stats")
            return _delegate("kb_build_index", tail)

        if args.command == "stats":
            data, transport = _network(args, "/stats", _fallback_stats)
        elif args.command == "resolve":
            q = urllib.parse.quote(args.query)
            data, transport = _network(args, f"/resolve?q={q}", lambda: _fallback_resolve(args))
        elif args.command == "corpus":
            q = urllib.parse.quote(args.query)
            data, transport = _network(args, f"/corpus?q={q}&k={args.k}",
                                       lambda: _fallback_corpus(args))
        elif args.command == "route":
            q = urllib.parse.quote(args.query)
            path = (f"/route?q={q}&budget={args.budget}&layer={args.layer}"
                    f"&no_corpus={1 if args.no_corpus else 0}")
            data, transport = _network(args, path, lambda: _fallback_route(args))
        elif args.command == "search":
            path = (f"/search?q={urllib.parse.quote(args.query)}&k={args.k}&mode={args.mode}"
                    f"&type={urllib.parse.quote(args.type)}&candidate_k={args.candidate_k}"
                    f"&rerank_k={args.rerank_k}"
                    f"&reranker_model={urllib.parse.quote(args.reranker_model)}"
                    f"&allow_download={1 if args.allow_download else 0}")
            data, transport = _network(args, path, lambda: _fallback_search(args))
        else:
            if args.plan or args.no_server:
                data, transport = _fallback_ask(args), "in-process"
            else:
                path = (f"/ask?q={urllib.parse.quote(args.query)}&strategy={args.strategy}"
                        f"&mode={args.mode}&k={args.k}&candidate_k={args.candidate_k}"
                        f"&rerank_k={args.rerank_k}&max_steps={args.max_steps}"
                        f"&budget={urllib.parse.quote(args.budget)}"
                        f"&no_graph={1 if args.no_graph else 0}"
                        f"&reranker_model={urllib.parse.quote(args.reranker_model)}"
                        f"&allow_download={1 if args.allow_download else 0}")
                data, transport = _network(args, path, lambda: _fallback_ask(args))
        data["transport"] = transport
        data["elapsed_ms"] = round((time.time() - started) * 1000, 1)
        if getattr(args, "json", False) or args.command == "route":
            print(K.json_dumps(data, ensure_ascii=False, indent=1))
        elif args.command == "ask":
            _print_ask(data)
        elif args.command in ("search", "corpus"):
            _print_search(data)
        elif args.command == "resolve":
            hits = data.get("alias_hits") or []
            print("（无别名命中）" if not hits else
                  "\n".join(f"  {a} -> {c}" for a, c in hits))
        else:
            print(K.json_dumps(data, ensure_ascii=False, indent=1))
        return 0
    except (RetrievalUnavailable, ServiceError) as exc:
        payload = {"schema_version": "kb.error.v1", "ok": False,
                   "error": {"type": type(exc).__name__, "message": str(exc)}}
        print(K.json_dumps(payload, ensure_ascii=False, indent=1),
              file=sys.stderr if not getattr(args, "json", False) else sys.stdout)
        return 3
    except (ValueError, OSError) as exc:
        print(f"参数错误：{exc}", file=sys.stderr)
        return 2


from kb_rag import RetrievalUnavailable  # noqa: E402

if __name__ == "__main__":
    K.console_encoding()
    sys.exit(main())
